const libraryRaw=fs.readFileSync(libraryPath,'utf8'),library=load(libraryRaw),idempotent=String(library.libraryVersion).endsWith(PHASE),priorChangesPath=path.join(artifactRoot,'incentives_question_changes.json'),priorProvenancePath=path.join(composerRoot,`${PHASE}.json`),priorChanges=idempotent&&fs.existsSync(priorChangesPath)?JSON.parse(fs.readFileSync(priorChangesPath,'utf8')):null,priorProvenance=idempotent&&fs.existsSync(priorProvenancePath)?JSON.parse(fs.readFileSync(priorProvenancePath,'utf8')):null;if(!String(library.libraryVersion).endsWith(PREVIOUS)&&!idempotent)throw new Error(`Expected ${PREVIOUS}; found ${library.libraryVersion}`);const module=library.concepts?.[CONCEPT];if(!module)throw new Error('Incentives module missing.');
const allLocations=m=>[...Object.entries(m.questions||{}).flatMap(([pool,list])=>(list||[]).map(question=>({pool,question}))),...(m.repairQuestions||[]).map(question=>({pool:'repair',question})),...(m.repairSeedQuestions||[]).map(question=>({pool:'repairSeed',question})),...(m.bridgeQuestions||[]).map(question=>({pool:'bridge',question}))],unique=m=>{const seen=new Set();return allLocations(m).filter(x=>!seen.has(idOf(x.question))&&seen.add(idOf(x.question)));},baselineLocations=m=>unique(m).filter(x=>!idOf(x.question).startsWith('P74-INC-'));if(baselineLocations(module).length!==33)throw new Error(`Expected 33 baseline records, found ${baselineLocations(module).length}.`);
const rewrites={
'ECON-MG-EASY-8':{q:'A grocery store gives shoppers a reusable-bag credit. Which statement identifies the incentive rather than the response?',options:['The credit raises the benefit of bringing a reusable bag','More shoppers bring reusable bags after the credit begins','The store uses fewer disposable bags by month end','Customers approve of the store’s environmental goal'],answer:'The credit raises the benefit of bringing a reusable bag',type:'application',skill:'incentive_identification',commonError:'Confusing the changed payoff with the behavior or outcome it may produce.',feedback:'The credit is the incentive; bag use and waste reduction are possible responses and outcomes.'},
'ECON-MG-MEDIUM-102':{q:'A neighborhood app awards a visible badge for weekly recycling. Participation rises among users who value recognition but barely changes for others. What is the best interpretation?',options:['A nonmonetary incentive can produce different responses across people','The badge guarantees recycling because everyone can see it','Recognition is not an incentive because no cash changes hands','Different responses prove the badge did not change any payoff'],answer:'A nonmonetary incentive can produce different responses across people',type:'application',skill:'heterogeneous_incentive_response',commonError:'Assuming incentives must be monetary or produce uniform behavior.',feedback:'Recognition can change expected benefits, while its importance varies across users.'},
'P52B-INC-E-001':{q:'A workplace gives public recognition to teams that finish safety training. What does the recognition directly change?',options:['The nonmonetary benefit of completing the training','The cash wage paid for every hour of training','The certainty that every employee completes training','The final safety outcome rather than the choice payoff'],answer:'The nonmonetary benefit of completing the training',type:'application',skill:'nonmonetary_incentive_response',commonError:'Treating incentive identification as vocabulary matching or assuming only cash matters.',feedback:'Recognition can raise the perceived benefit of completing training without guaranteeing it.'},
'ECON-MG-LEGENDARY-9079':{q:'A subscription service makes cancellation require a phone call but lets upgrades occur with one click. Cancellations fall and complaints rise. What is the strongest inference?',options:['The rule raises the time cost of cancellation and may retain users while worsening experience','Lower cancellation proves every retained user prefers the service','The inconvenience is not an incentive because it is nonmonetary','Complaints show the cancellation rule had no behavioral effect'],answer:'The rule raises the time cost of cancellation and may retain users while worsening experience',type:'synthesis',skill:'nonmonetary_incentive_response',commonError:'Ignoring inconvenience as a cost or treating retention as complete success.',feedback:'The asymmetric process changes the payoff to cancellation and can create both intended retention and dissatisfaction.'},
'ECON-MG-LEGENDARY-9085':{q:'A software platform ranks creators by daily posting frequency. Posting rises, but creators split one useful guide into many thin updates. What does the response reveal?',options:['Creators optimized the visible metric while substituting away from unmeasured quality','The ranking failed to create an incentive because guide quality fell','More posts guarantee more useful information for every reader','A noncash ranking cannot alter creator behavior'],answer:'Creators optimized the visible metric while substituting away from unmeasured quality',type:'synthesis',skill:'metric_gaming',commonError:'Treating improvement in a measured target as improvement in the underlying objective.',feedback:'The ranking rewards frequency, so creators can game that metric at the expense of quality.'},
'ECON-MG-EASYBOSS-2006':{q:'A café doubles loyalty points for visits before 9 a.m. Which response would economic reasoning most directly predict?',options:['Some customers become more likely to visit earlier','Every customer must switch to an early visit','The points matter only if converted directly to cash','Earlier visits prove customers approve of the café’s policy'],answer:'Some customers become more likely to visit earlier',type:'application',skill:'behavior_response_to_incentives',commonError:'Treating an incentive as a guarantee or requiring it to be cash.',feedback:'Extra points raise the benefit of early visits, making that behavior more likely for some customers.'},
'P52B-INC-BR-001':{q:'A professor adds one point for each discussion post. How does marginal analysis connect to the incentive students face?',options:['The extra point raises the marginal benefit of one more post','The total course grade becomes the cost of every post','Scarcity disappears once points are available','The added point guarantees that every post improves learning'],answer:'The extra point raises the marginal benefit of one more post',type:'bridge',skill:'marginal_analysis_to_incentives',secondaryConceptIds:['marginal-analysis'],commonError:'Missing that an incentive changes the next action’s marginal payoff.',feedback:'The added point changes the marginal benefit of submitting another post; quality is a separate outcome.'},
'P52B-INC-B2-001':{q:'A bonus tied only to sales volume causes excessive discounting. What happened?',options:['Workers ignored the bonus and changed discounting for unrelated market reasons','Workers optimized the rewarded metric rather than total profit','The bonus eliminated every tradeoff involved in making sales','Sales volume became a public good shared equally by all firms'],answer:'Workers optimized the rewarded metric rather than total profit',type:'application',skill:'incentive_design_tradeoff',commonError:'Evaluating the rewarded metric without examining its effect on total profit.',feedback:'The bonus raises the payoff to volume even when discounts make some sales unprofitable.'},
'P52B-INC-R-001':{q:'Which statement best captures an economic incentive?',options:['A change in expected benefits or costs that can alter behavior','Only a direct cash payment that rewards the intended behavior','A rule that guarantees every person makes the same choice','The final outcome observed after a policy is introduced'],answer:'A change in expected benefits or costs that can alter behavior',type:'application',skill:'incentive_definition',commonError:'Defining incentives as cash only, guaranteed behavior, or final outcomes.',feedback:'An incentive changes the payoff to a choice; it need not be monetary or guarantee a result.'},
'P52B-INC-R-002':{q:'Which example is an unintended response to an incentive?',options:['A planned result that occurs exactly as policy designers expected','People respond to a rule in a way that produces an unplanned result','Evidence that the original rule created no behavioral pressure at all','A response that every person makes in exactly the same way'],answer:'People respond to a rule in a way that produces an unplanned result',type:'application',skill:'incentives_unintended_consequences',commonError:'Treating an unplanned response as proof that no incentive existed.',feedback:'People can respond to the changed payoff while producing a side effect the designer did not intend.'}
};
const additions={
easy:[
{id:'P74-INC-E-005',q:'A library begins charging a late fee. What response becomes more likely?',options:['More borrowers return books on time','Every borrower returns every book early','Borrowers view late returns as more rewarding','The fee guarantees that no book is ever late'],answer:'More borrowers return books on time',skill:'behavior_response_to_incentives',commonError:'Turning a likely directional response into guaranteed compliance.',feedback:'The fee raises the cost of delay, so timely return becomes more likely.'},
{id:'P74-INC-E-006',q:'A school offers preferred event seating to students with strong attendance. What kind of payoff changed?',options:['A nonmonetary benefit of attending school','The cash wage paid for attending school','The legal penalty for missing school','The final attendance outcome itself'],answer:'A nonmonetary benefit of attending school',skill:'nonmonetary_incentive_response',commonError:'Assuming only direct cash changes can be incentives.',feedback:'Preferred seating is a noncash benefit that can make attendance more attractive.'},
{id:'P74-INC-E-007',q:'A city adds a refundable deposit to beverage bottles. Which choice identifies the incentive?',options:['Recovering the deposit by returning the bottle','The number of bottles ultimately recycled','Public support for cleaner streets','A guarantee that every bottle is returned'],answer:'Recovering the deposit by returning the bottle',skill:'incentive_identification',commonError:'Confusing the incentive with the eventual recycling outcome.',feedback:'The refund changes the benefit of returning a bottle; recycling is a possible result.'},
{id:'P74-INC-E-008',q:'A sales representative earns a commission on each completed sale. What does the commission directly do?',options:['Raises the benefit of completing another sale','Guarantees that every customer will buy','Makes product quality irrelevant to buyers','Removes the representative’s opportunity costs'],answer:'Raises the benefit of completing another sale',skill:'positive_incentive_response',commonError:'Treating a stronger payoff as certain success.',feedback:'A commission increases the expected benefit of another sale without guaranteeing it.'},
{id:'P74-INC-E-009',q:'An insurer raises the copay for an optional clinic visit. Holding other factors fixed, patients are most likely to:',options:['Become less likely to schedule the visit','Schedule every optional visit immediately','Ignore the copay because costs are not incentives','Treat the copay as a reward for using care'],answer:'Become less likely to schedule the visit',skill:'negative_incentive_response',commonError:'Reversing the response to a higher out-of-pocket cost.',feedback:'The higher copay raises the cost of the visit, tending to reduce its use.'},
{id:'P74-INC-E-010',q:'A shop offers free shipping only on orders above $50. Which behavior does the threshold encourage?',options:['Adding items to bring some orders above $50','Reducing every order below $50','Buying exactly the same basket in every case','Avoiding online shopping regardless of preferences'],answer:'Adding items to bring some orders above $50',skill:'threshold_incentive_response',commonError:'Ignoring the behavioral pressure created near a threshold.',feedback:'Customers near $50 gain free shipping by adding items, so basket size may rise.'}
],
medium:[
{id:'P74-INC-M-005',q:'A warehouse pays a bonus for packages shipped per hour but charges workers for verified damage. What response is most plausible?',options:['Workers balance speed against the expected cost of damage','Workers maximize speed because only rewards affect behavior','Damage must fall to zero for the incentives to exist','Every worker chooses the same speed regardless of risk'],answer:'Workers balance speed against the expected cost of damage',skill:'competing_incentives',commonError:'Considering one incentive while ignoring a simultaneous opposing incentive.',feedback:'The speed bonus and damage consequence change different parts of the worker’s payoff.'},
{id:'P74-INC-M-006',q:'A parking fine doubles, but patrols become rare. Why might violations change little?',options:['The expected penalty may remain small because enforcement is unlikely','A larger statutory fine can never affect behavior','Drivers respond only to rewards, not penalties','Low enforcement guarantees more violations by every driver'],answer:'The expected penalty may remain small because enforcement is unlikely',skill:'enforcement_incentives',commonError:'Looking only at the posted penalty and ignoring enforcement probability.',feedback:'Behavior responds to the expected consequence, which depends on both size and enforcement.'},
{id:'P74-INC-M-007',q:'Two employees receive the same attendance bonus. One changes her schedule; the other has caregiving duties and cannot. What does this show?',options:['The same incentive can produce different responses under different constraints','The bonus was not an incentive for either employee','A valid incentive must change everyone’s behavior','Constraints matter only when incentives are nonmonetary'],answer:'The same incentive can produce different responses under different constraints',skill:'heterogeneous_incentive_response',commonError:'Assuming identical payoffs generate identical responses.',feedback:'The bonus changes payoffs, but constraints and alternatives shape each response.'},
{id:'P74-INC-M-008',q:'A delivery app rewards acceptance rate. Some drivers accept poor-fit jobs and cancel later. Which design issue appears?',options:['The measured target encourages substitution into a different undesirable action','The reward cannot be an incentive because cancellations rose','Acceptance rate measures service quality perfectly','The response proves drivers ignored the metric'],answer:'The measured target encourages substitution into a different undesirable action',skill:'metric_gaming',commonError:'Evaluating only the rewarded metric and missing substitution.',feedback:'Drivers improve acceptance statistics while shifting the problem into later cancellations.'},
{id:'P74-INC-M-009',q:'A company offers either a $40 bonus or public recognition for completing training. Some workers value one more than the other. What follows?',options:['Monetary and nonmonetary incentives can differ in strength across people','Only the cash option can change expected benefits','Recognition guarantees completion among all workers','Different preferences mean neither option is an incentive'],answer:'Monetary and nonmonetary incentives can differ in strength across people',skill:'incentive_types',commonError:'Assuming all people rank monetary and nonmonetary incentives identically.',feedback:'Both rewards can alter benefits, but their value depends on the decision-maker.'},
{id:'P74-INC-M-010',q:'A gym charges a missed-appointment fee but waives it when members cancel a day ahead. Which margin does the rule most directly target?',options:['Whether members cancel early instead of simply not appearing','Whether every member continues the gym membership','Whether exercise produces health benefits','Whether members morally approve of cancellation rules'],answer:'Whether members cancel early instead of simply not appearing',skill:'behavioral_margin_identification',commonError:'Confusing the targeted choice margin with broader outcomes or approval.',feedback:'The avoidable fee makes advance cancellation more attractive relative to a no-show.'}
],
hard:[
{id:'P74-INC-H-005',q:'A hospital is paid for each procedure but penalized for readmissions. Which response best reflects both incentives?',options:['It may increase profitable procedures while investing in follow-up that lowers readmissions','It must reduce every procedure because penalties dominate rewards','It will ignore follow-up because only direct payments affect behavior','The payment design guarantees the socially optimal treatment mix'],answer:'It may increase profitable procedures while investing in follow-up that lowers readmissions',skill:'multiple_behavioral_margins',commonError:'Reasoning from only one component of a multi-part payment system.',feedback:'Procedure payments and readmission penalties act on different behavioral margins.'},
{id:'P74-INC-H-006',q:'A school rewards high test pass rates. Administrators shift tutoring toward students just below the cutoff and away from students far behind. What is the strongest interpretation?',options:['A threshold metric changes where effort has the highest measured payoff','The reward guarantees equal gains for every student','Tutoring shifts prove the pass-rate reward was not an incentive','The stated goal determines behavior more than the measured target'],answer:'A threshold metric changes where effort has the highest measured payoff',skill:'threshold_incentive_response',commonError:'Ignoring how a cutoff redirects effort across people.',feedback:'Effort near the pass threshold produces the largest measured return, even if broader learning is the goal.'},
{id:'P74-INC-H-007',q:'An environmental fee applies only when emissions exceed a monthly cap. A factory shifts production between months to remain below the cap without lowering annual emissions. What happened?',options:['The threshold changed timing rather than the underlying annual outcome','The fee created no incentive because annual emissions stayed constant','Any legal response must satisfy the policy’s broader objective','A fee cannot affect production timing'],answer:'The threshold changed timing rather than the underlying annual outcome',skill:'incentives_unintended_consequences',commonError:'Equating compliance with the measured threshold to achievement of the ultimate goal.',feedback:'The incentive altered the monitored margin while leaving annual emissions unchanged.'},
{id:'P74-INC-H-008',q:'A procurement office rewards the lowest bid and later faces frequent change orders. Which redesign most directly addresses the incentive problem?',options:['Evaluate expected total cost and performance, not the opening bid alone','Raise the reward for submitting any low opening bid','Ignore change orders because the initial metric improved','Require every bidder to choose the same production method'],answer:'Evaluate expected total cost and performance, not the opening bid alone',skill:'incentive_design_tradeoff',commonError:'Rewarding a proxy that omits costly dimensions of the true objective.',feedback:'A broader metric reduces the payoff to lowballing the initial bid and recovering revenue later.'},
{id:'P74-INC-H-009',q:'A deductible rises from $100 to $1,000. Which prediction is best without knowing patient income, health risk, or alternatives?',options:['Use of covered services tends to fall, but response size can vary widely','Every patient reduces care by the same percentage','No response is possible because insurance already exists','The higher deductible guarantees better health decisions'],answer:'Use of covered services tends to fall, but response size can vary widely',skill:'heterogeneous_incentive_response',commonError:'Inferring an identical or guaranteed response from a common price change.',feedback:'The higher out-of-pocket cost creates directional pressure, while circumstances shape magnitude.'},
{id:'P74-INC-H-010',q:'A police department rewards citation counts. Citations rise, public trust falls, and serious-case work receives less time. Which conclusion is warranted?',options:['The metric changed behavior but did not capture the department’s full objective','Falling trust proves citation rewards cannot influence officers','More citations establish that public safety necessarily improved','Economic analysis requires moral approval of the reward'],answer:'The metric changed behavior but did not capture the department’s full objective',skill:'metric_gaming',commonError:'Treating a rewarded count as identical to the underlying public objective.',feedback:'The reward affects behavior, but the observed metric omits trust and case importance.'}
],
elite:[
{id:'P74-INC-EL-003',q:'A nonprofit grant rewards clients placed in jobs for 30 days. Providers avoid applicants needing intensive support and favor easy placements. Which redesign best preserves effort while limiting selection?',options:['Reward sustained outcomes while adjusting targets for client difficulty','Pay only for the raw number of 30-day placements','Remove all performance information from funding decisions','Assume selection disappears when providers share the mission'],answer:'Reward sustained outcomes while adjusting targets for client difficulty',skill:'incentive_design_under_imperfect_measurement',commonError:'Using an unadjusted proxy that rewards selection instead of underlying impact.',feedback:'Longer outcomes and risk adjustment better align the measured target with the mission.'},
{id:'P74-INC-EL-004',q:'An energy plan combines a peak-hour surcharge, a monthly conservation badge, and a rebate for smart thermostats. Which analysis is strongest?',options:['Households weigh multiple monetary and nonmonetary incentives differently across usage margins','The three incentives must produce the same response in every household','Only the surcharge matters because costs always dominate benefits','Any decline in peak use proves total energy use also fell'],answer:'Households weigh multiple monetary and nonmonetary incentives differently across usage margins',skill:'multiple_behavioral_margins',commonError:'Collapsing several incentives and response margins into one guaranteed outcome.',feedback:'Each feature changes a different payoff, and household constraints determine the resulting mix.'}
],
legendary:[
{id:'P74-INC-L-007',q:'A teacher bonus depends on class-average scores. Teachers provide extra review but also discourage low-performing students from testing. What should an evaluator conclude?',options:['The metric induced both instructional effort and selection behavior','The bonus failed because one unintended response occurred','Higher average scores prove learning rose for every student','Selection cannot be an incentive response because it is against policy'],answer:'The metric induced both instructional effort and selection behavior',skill:'metric_gaming',commonError:'Looking only at the intended response or only at the side effect.',feedback:'The same reward can improve preparation and create pressure to alter who is measured.'},
{id:'P74-INC-L-008',q:'A university receives funding for degrees completed on time. Advising improves, but difficult required courses are weakened. What is the strongest interpretation?',options:['The completion target changes several margins, including quality that the metric omits','Weaker courses prove funding cannot influence completion decisions','On-time completion is identical to educational quality','The policy outcome is guaranteed because funding increased'],answer:'The completion target changes several margins, including quality that the metric omits',skill:'incentive_design_tradeoff',commonError:'Equating the observable target with the complete educational objective.',feedback:'Programs can improve advising and relax standards because both raise the rewarded metric.'},
{id:'P74-INC-L-009',q:'A congestion charge is announced, but drivers believe cameras identify only 5% of violators. Which factor most limits deterrence?',options:['The low perceived probability of paying the charge','The charge is negative rather than positive','Driving has benefits as well as costs','A legal charge cannot change expected costs'],answer:'The low perceived probability of paying the charge',skill:'enforcement_incentives',commonError:'Ignoring perceived enforcement when evaluating an incentive’s strength.',feedback:'The expected cost depends on both the charge and the chance it is imposed.'},
{id:'P74-INC-L-010',q:'A health insurer waives copays for preventive visits but raises emergency-room copays. Which response is most defensible?',options:['Some care may shift toward prevention, with response varying by access and health needs','Every emergency visit disappears because its price rose','All patients respond identically because they face the same schedule','Waiving a copay is not an incentive because no payment is received'],answer:'Some care may shift toward prevention, with response varying by access and health needs',skill:'competing_incentives',commonError:'Predicting certain, uniform substitution from a common payment schedule.',feedback:'Relative costs change, but constraints and medical need shape actual substitution.'},
{id:'P74-INC-L-011',q:'A city pays restaurants for each kilogram of food donated. Donations rise, but some restaurants overproduce near closing time. What does this show?',options:['A reward can increase the target and also encourage wasteful production','Overproduction proves donations were never incentivized','The payment guarantees total food waste will decline','Only penalties can create unintended responses'],answer:'A reward can increase the target and also encourage wasteful production',skill:'incentives_unintended_consequences',commonError:'Assuming intended and unintended responses cannot occur together.',feedback:'The donation payment raises one benefit while also changing production incentives.'},
{id:'P74-INC-L-012',q:'A housing program withdraws $1 of aid for each $1 of additional earnings over a threshold. Which behavioral pressure follows?',options:['Earning just above the threshold may provide little immediate net gain','Every recipient stops working completely','The rule rewards additional earnings dollar for dollar','Aid withdrawal is an outcome rather than an incentive'],answer:'Earning just above the threshold may provide little immediate net gain',skill:'threshold_incentive_response',commonError:'Ignoring how benefit withdrawal changes the payoff to extra earnings.',feedback:'The phaseout can sharply reduce the net benefit of crossing the earnings threshold.'},
{id:'P74-INC-L-013',q:'A credit card offers triple points for travel. One customer travels more; another keeps the same trips and switches cards. What is the lesson?',options:['The same reward can change different margins for different consumers','Only the customer who travels more responded to the incentive','A reward is ineffective unless total travel rises for everyone','Card switching cannot be an incentive response'],answer:'The same reward can change different margins for different consumers',skill:'heterogeneous_incentive_response',commonError:'Recognizing only one possible behavioral margin.',feedback:'The reward can affect travel quantity, payment choice, or neither, depending on alternatives.'},
{id:'P74-INC-L-014',q:'A factory posts team safety rankings without cash prizes. Reporting rises, but some teams relabel minor incidents as near misses. Which conclusion is best?',options:['A nonmonetary status incentive improved reporting while creating classification gaming','No incentive exists because rankings do not change wages','Relabeling proves rankings cannot affect behavior','Higher reported safety guarantees fewer actual injuries'],answer:'A nonmonetary status incentive improved reporting while creating classification gaming',skill:'nonmonetary_incentive_response',commonError:'Ignoring status incentives or unmeasured changes in classification.',feedback:'Recognition changes social payoffs, and teams may also optimize how incidents are recorded.'},
{id:'P74-INC-L-015',q:'A charity matches the first $100 of each donation. A donor planning to give $300 still gives $300. How should the match be evaluated for that donor?',options:['It transfers funds but does not change this donor’s marginal giving decision','It necessarily causes an additional $100 donation','The donor did not face an incentive because giving was planned','The match reduces the benefit of donating'],answer:'It transfers funds but does not change this donor’s marginal giving decision',skill:'marginal_incentive_effect',commonError:'Counting all subsidized activity as behavior caused by the incentive.',feedback:'The match applies to the gift, but this donor’s amount is unchanged relative to the alternative.'},
{id:'P74-INC-L-016',q:'A platform threatens suspension for false listings, but enforcement reviews only complaints from paying users. What response is most plausible?',options:['Sellers may target deception toward users least likely to trigger review','Suspension guarantees that all listings become accurate','Uneven enforcement cannot alter where misconduct occurs','The rule is not an incentive until a suspension happens'],answer:'Sellers may target deception toward users least likely to trigger review',skill:'enforcement_incentives',commonError:'Ignoring how selective enforcement redirects behavior.',feedback:'The expected cost varies with the chance a listing is reviewed, creating a substitution margin.'},
{id:'P74-INC-L-017',q:'A government contract pays builders for finishing early and penalizes visible defects, but not hidden maintenance problems. What risk remains?',options:['Effort may shift toward speed and visible quality while hidden durability suffers','Every dimension of quality improves because defects are penalized','The early-finish reward and defect penalty cancel exactly','Hidden durability cannot respond to incentives because it is unobserved'],answer:'Effort may shift toward speed and visible quality while hidden durability suffers',skill:'incentive_design_under_imperfect_measurement',commonError:'Assuming measured dimensions represent total performance.',feedback:'Unmeasured durability can be sacrificed while rewarded and monitored dimensions improve.'},
{id:'P74-INC-L-018',q:'A farm subsidy pays per acre planted with one crop. Farmers expand acreage onto less suitable land. Which part is the incentive and which is the response?',options:['Per-acre payment is the incentive; expansion onto marginal land is a response','Expanded acreage is the incentive; payment is the outcome','Crop suitability is the incentive; planting is moral approval','The subsidy is neither because planting was already possible'],answer:'Per-acre payment is the incentive; expansion onto marginal land is a response',skill:'incentive_vs_outcome',commonError:'Interchanging a payoff change with the behavior it induces.',feedback:'The payment changes the benefit of each planted acre; land expansion is a resulting choice.'},
{id:'P74-INC-L-019',q:'An employer replaces a late-arrival reprimand with a small fee deducted from pay. Some workers become more punctual; others treat lateness as a purchasable option. What does this show?',options:['Changing the form of a consequence can change its social meaning and produce mixed responses','A fee cannot deter behavior because it is monetary','Mixed responses prove neither consequence was an incentive','Every worker must interpret the fee as moral approval'],answer:'Changing the form of a consequence can change its social meaning and produce mixed responses',skill:'monetary_nonmonetary_interaction',commonError:'Assuming monetary and social consequences are interchangeable for everyone.',feedback:'The fee changes monetary cost while possibly weakening a nonmonetary norm.'},
{id:'P74-INC-L-020',q:'A transit agency offers off-peak discounts. Flexible riders shift trips, while shift workers cannot. Which evaluation is strongest?',options:['The price incentive changes trip timing mainly for riders with feasible alternatives','The discount is not an incentive because some riders cannot respond','All riders receive identical benefits from changing travel time','The policy guarantees total ridership will rise'],answer:'The price incentive changes trip timing mainly for riders with feasible alternatives',skill:'heterogeneous_incentive_response',commonError:'Treating inability to respond as evidence that no incentive exists.',feedback:'The discount changes relative prices, but schedule constraints determine who can act on it.'},
{id:'P74-INC-L-021',q:'A streaming service removes a cancellation fee but adds a loyalty reward after twelve months. Which margin is most directly affected?',options:['The relative payoff to staying through the twelfth month','The quality of every program on the service','The certainty that all subscribers remain','Subscribers’ moral judgment of loyalty programs'],answer:'The relative payoff to staying through the twelfth month',skill:'behavioral_margin_identification',commonError:'Confusing the targeted retention choice with broad outcomes or approval.',feedback:'The reward changes the benefit of remaining until a specific time threshold.'},
{id:'P74-INC-L-022',q:'A warranty pays repair shops a flat amount per claim. Shops begin avoiding complex claims and completing simple ones quickly. What caused the pattern?',options:['A uniform payment changes the payoff differently for low-cost and high-cost claims','The flat payment guarantees equal service across claims','Avoiding difficult cases proves payments cannot affect selection','Claim complexity is irrelevant whenever prices are fixed'],answer:'A uniform payment changes the payoff differently for low-cost and high-cost claims',skill:'selection_incentives',commonError:'Ignoring how a common payment creates heterogeneous margins across cases.',feedback:'Simple claims become more profitable relative to complex ones, encouraging selection.'},
{id:'P74-INC-L-023',q:'A sports contract pays a large bonus for games played. An injured athlete returns early and performs poorly. What is the careful conclusion?',options:['The bonus increased pressure to play but did not guarantee a beneficial outcome','The poor performance proves the bonus was not an incentive','Bonuses influence effort but never participation decisions','Playing establishes that the athlete approved of the contract design'],answer:'The bonus increased pressure to play but did not guarantee a beneficial outcome',skill:'incentive_probability_not_certainty',commonError:'Equating a behavioral response with a desirable or certain result.',feedback:'The bonus changed the payoff to participation, while health and performance remained uncertain.'},
{id:'P74-INC-L-024',q:'A nonprofit grant rewards the number of people enrolled, not services completed. Enrollment rises and completion falls. Which measure is being optimized?',options:['The funded enrollment count rather than the broader service objective','Completion because it is the organization’s stated mission','Both measures equally because they concern the same clients','Neither measure because nonprofits do not respond to funding'],answer:'The funded enrollment count rather than the broader service objective',skill:'metric_gaming',commonError:'Assuming mission statements dominate the payoff attached to a measured target.',feedback:'The grant rewards entry into the program, so effort shifts toward enrollment rather than completion.'},
{id:'P74-INC-L-025',q:'A delivery platform guarantees a minimum hourly payment only while drivers are actively carrying orders. Which response is plausible?',options:['Drivers may favor longer trips or avoid unpaid waiting when choosing orders','Every driver accepts the shortest available trip','The guarantee removes all opportunity costs of time','Payment rules cannot change which orders drivers select'],answer:'Drivers may favor longer trips or avoid unpaid waiting when choosing orders',skill:'opportunity_cost_incentives',commonError:'Ignoring how compensation changes the opportunity cost of time and order selection.',feedback:'The rule changes which activities count as paid time, altering the relative payoff to orders.'},
{id:'P74-INC-L-026',q:'A city raises water prices after a monthly allowance and also publishes neighborhood conservation rankings. What response should be expected?',options:['Price and status pressures may reduce use by different amounts across households','The ranking is irrelevant because only prices are incentives','Every household cuts water use by the same quantity','Lower use is guaranteed wherever both incentives exist'],answer:'Price and status pressures may reduce use by different amounts across households',skill:'multiple_behavioral_margins',commonError:'Assuming one incentive type matters or that responses are uniform.',feedback:'Both monetary cost and social comparison can affect use, with varied strength.'},
{id:'P74-INC-L-027',q:'A criminal fine is tripled while the probability of detection falls by two-thirds. Without more information, what can be concluded?',options:['The expected penalty may be similar, though perceptions and risk attitudes can still change response','Deterrence must triple because the posted fine tripled','Deterrence must disappear because detection fell','No incentive exists until someone is actually fined'],answer:'The expected penalty may be similar, though perceptions and risk attitudes can still change response',skill:'enforcement_incentives',commonError:'Using only penalty size or only detection probability.',feedback:'Expected consequences combine severity and enforcement, while perceived risk also matters.'}
],
boss:[
{id:'P74-INC-EB-004',tier:'easyBoss',q:'A store offers a one-day discount on umbrellas before a storm. What response is most directly predicted?',options:['Some customers become more likely to buy that day','Every shopper buys an umbrella','The discount guarantees the store earns more profit','Customers must morally approve of discounts'],answer:'Some customers become more likely to buy that day',skill:'behavior_response_to_incentives',commonError:'Treating a lower price as a guaranteed purchase or profit outcome.',feedback:'The discount raises the relative benefit of buying now for some customers.'},
{id:'P74-INC-MB-004',tier:'mediumBoss',q:'A call center rewards short calls and separately penalizes repeat complaints. How should agents respond?',options:['Balance speed against the risk that poor service triggers repeat complaints','Make every call as short as possible because rewards dominate penalties','Ignore both rules unless all agents respond identically','Guarantee perfect service because two incentives are present'],answer:'Balance speed against the risk that poor service triggers repeat complaints',skill:'competing_incentives',commonError:'Ignoring one side of a multi-part incentive system.',feedback:'Agents face a reward for speed and an expected cost for unresolved problems.'},
{id:'P74-INC-FB-001',tier:'finalBoss',q:'A hospital bonus rewards low average treatment cost. Managers discharge patients earlier, but readmissions rise. Which redesign best aligns the incentive with patient outcomes?',options:['Include readmissions and health outcomes alongside treatment cost','Increase the reward for low initial cost alone','Judge success only by the number of discharges','Remove monitoring because outcomes vary across patients'],answer:'Include readmissions and health outcomes alongside treatment cost',skill:'incentive_design_under_imperfect_measurement',commonError:'Rewarding a narrow cost metric that omits downstream outcomes.',feedback:'A broader measure reduces the payoff to cost cutting that shifts expense or harm into readmissions.'},
{id:'P74-INC-FB-002',tier:'finalBoss',q:'A speeding fine rises from $100 to $500, but camera uptime falls from 80% to 10%. What is the best evaluation?',options:['Deterrence depends on the combined expected and perceived consequence, not the fine alone','The fivefold fine guarantees five times as much compliance','Lower camera uptime makes the fine a positive incentive','The policy has no incentive effect until every driver is caught'],answer:'Deterrence depends on the combined expected and perceived consequence, not the fine alone',skill:'enforcement_incentives',commonError:'Evaluating severity without enforcement probability.',feedback:'A larger fine can be offset by a much lower chance of detection.'},
{id:'P74-INC-FB-003',tier:'finalBoss',q:'A university funds departments for graduates employed within 30 days. Programs steer students toward quick-placement jobs and away from longer searches for better matches. What is the central design problem?',options:['The measured deadline rewards placement speed rather than match quality','Employment funding cannot influence advising behavior','Quick placement guarantees the best long-run outcome','The stated career goal prevents any unintended response'],answer:'The measured deadline rewards placement speed rather than match quality',skill:'metric_gaming',commonError:'Confusing the measured proxy with the underlying goal.',feedback:'Departments gain from hitting the short deadline even if longer searches would improve matches.'},
{id:'P74-INC-FB-004',tier:'finalBoss',q:'A conservation policy combines a usage fee, public recognition, and exemptions for medical needs. Which assessment is most defensible?',options:['Different households face different effective incentives, so response and burden will vary','The usage fee guarantees identical reductions for all households','Recognition is irrelevant because it is not money','Exemptions prove the policy has no behavioral effect'],answer:'Different households face different effective incentives, so response and burden will vary',skill:'heterogeneous_incentive_response',commonError:'Ignoring multiple incentive types, constraints, and exemptions.',feedback:'Prices, status, and exemptions change payoffs differently across households.'}
],
legendaryBoss:[
{id:'P74-INC-LB-004',q:'A news site pays writers for clicks. Headlines become sensational, traffic rises, and subscriber retention falls. What is the strongest diagnosis?',options:['The click metric rewards attention while omitting long-run reader trust','More clicks prove the compensation system improved total value','Retention loss means writers did not respond to incentives','A payment cannot affect headline choices without changing article length'],answer:'The click metric rewards attention while omitting long-run reader trust',skill:'metric_gaming',commonError:'Treating a short-run proxy as the complete objective.',feedback:'Writers optimize the rewarded metric, potentially sacrificing unmeasured retention.',bossStage:'opening'},
{id:'P74-INC-LB-005',q:'Two households face the same $50 peak-energy surcharge. One shifts appliance use; the other has medical equipment that must run continuously. What should the analyst infer?',options:['The surcharge changes payoffs for both, but constraints produce different responses','The second household proves the surcharge is not an incentive','A common price must cause a common quantity change','Only the household that shifts use faces an opportunity cost'],answer:'The surcharge changes payoffs for both, but constraints produce different responses',skill:'heterogeneous_incentive_response',commonError:'Assuming identical responses or denying an incentive when response is constrained.',feedback:'The price changes expected cost, while feasibility determines behavior.',bossStage:'middle'},
{id:'P74-INC-LB-006',q:'A safety regulator doubles penalties but inspects firms once every ten years. Which reform most directly strengthens the behavioral incentive?',options:['Increase credible inspection probability while maintaining meaningful penalties','Announce an even larger maximum penalty without changing inspections','Replace all penalties with a statement of the policy goal','Assume firms respond identically to the existing rule'],answer:'Increase credible inspection probability while maintaining meaningful penalties',skill:'enforcement_incentives',commonError:'Focusing on statutory severity rather than expected enforcement.',feedback:'A credible chance of detection makes the consequence relevant to current choices.',bossStage:'final'},
{id:'P74-INC-LB-007',q:'A firm pays sales commissions but charges back commissions on returns. Which behavior best reflects the combined design?',options:['Representatives weigh an immediate sale against the risk of a later return','Representatives pursue every sale because commissions are positive','Chargebacks guarantee no unsuitable product is sold','The two rules eliminate all differences across representatives'],answer:'Representatives weigh an immediate sale against the risk of a later return',skill:'competing_incentives',commonError:'Considering the reward while ignoring the contingent penalty.',feedback:'The chargeback changes the expected value of low-quality sales.',bossStage:'opening'},
{id:'P74-INC-LB-008',q:'Remote work lowers commuting time for an employee, making a job offer more attractive even though salary is unchanged. What created the incentive response?',options:['A lower opportunity cost of accepting the job','A cash bonus hidden in the salary','A guaranteed increase in job satisfaction','Moral approval of remote work'],answer:'A lower opportunity cost of accepting the job',skill:'opportunity_cost_incentives',secondaryConceptIds:['opportunity-cost'],commonError:'Looking only for explicit cash rewards and missing a changed alternative cost.',feedback:'Reduced commuting time changes the relative cost of choosing the job.',bossStage:'middle'},
{id:'P74-INC-LB-009',q:'A grant rewards clinics for vaccinations administered. Clinics run outreach campaigns, but some record duplicate entries. Which conclusion best separates incentive from outcome?',options:['The payment changed outreach and reporting payoffs; vaccination coverage must be measured independently','Recorded doses are the incentive and the grant is the outcome','Duplicate entries prove outreach did not respond to the grant','The stated health goal guarantees the reported metric is accurate'],answer:'The payment changed outreach and reporting payoffs; vaccination coverage must be measured independently',skill:'incentive_vs_outcome',commonError:'Equating the rewarded record count with the final health outcome.',feedback:'The incentive affects multiple behaviors, while true coverage is a separate result.',bossStage:'final'}
],
repair:[
{id:'P74-INC-R-003',q:'A $500 attendance bonus is offered, but an employee misses work during a medical emergency. Was the bonus still an incentive?',options:['Yes; it changed the payoff but did not guarantee attendance','No; an incentive exists only when behavior changes','No; bonuses must overcome every constraint','Yes; it guaranteed attendance for all other workers'],answer:'Yes; it changed the payoff but did not guarantee attendance',skill:'incentive_probability_not_certainty',commonError:'Defining an incentive by guaranteed compliance.',feedback:'An incentive changes behavioral pressure; emergencies and other constraints can still dominate.'},
{id:'P74-INC-R-004',q:'An economist says a fine creates an incentive to avoid an action. Does that statement approve of the fine?',options:['No; identifying a changed cost is separate from moral approval','Yes; economic analysis always endorses the incentive','Yes; only approved penalties affect behavior','No; fines are outcomes rather than incentives'],answer:'No; identifying a changed cost is separate from moral approval',skill:'incentive_analysis_not_approval',commonError:'Confusing descriptive incentive analysis with moral endorsement.',feedback:'Economists can predict a response without judging the policy desirable.'},
{id:'P74-INC-R-005',q:'Can two people respond differently to the same parking fee?',options:['Yes; constraints, preferences, and alternatives can differ','No; the same dollar fee produces the same response','Only if one person misunderstands the fee','No; different responses mean the fee is not an incentive'],answer:'Yes; constraints, preferences, and alternatives can differ',skill:'heterogeneous_incentive_response',commonError:'Assuming the same incentive creates identical behavior.',feedback:'A common payoff change can matter differently across decision-makers.'},
{id:'P74-INC-R-006',q:'A school gives public recognition rather than cash for attendance. Can recognition be an incentive?',options:['Yes; nonmonetary benefits can change behavior','No; only money changes benefits or costs','Only if recognition has a fixed cash value','No; recognition is the final policy outcome'],answer:'Yes; nonmonetary benefits can change behavior',skill:'nonmonetary_incentive_response',commonError:'Restricting incentives to monetary rewards and penalties.',feedback:'Status, convenience, rules, and recognition can all change perceived payoffs.'},
{id:'P74-INC-R-007',q:'A large fine is almost never enforced. Why may it have little effect?',options:['The expected consequence is weak when detection is very unlikely','Penalties cannot be incentives','The fine guarantees compliance despite enforcement','Only the stated policy goal influences behavior'],answer:'The expected consequence is weak when detection is very unlikely',skill:'enforcement_incentives',commonError:'Ignoring enforcement probability.',feedback:'Expected and perceived consequences depend on both severity and the chance of enforcement.'}
],
bridge:[
{id:'P74-INC-BR-002',q:'Scarcity forces a student to choose between work and study. How can a higher wage create an incentive?',options:['It raises the opportunity cost of study relative to work','It eliminates the need to choose between uses of time','It guarantees the student stops studying','It changes scarcity into abundance'],answer:'It raises the opportunity cost of study relative to work',skill:'scarcity_opportunity_cost_to_incentives',secondaryConceptIds:['scarcity-and-tradeoffs','opportunity-cost'],commonError:'Missing how a changed alternative payoff alters a scarce-resource choice.',feedback:'With limited time, the higher wage makes study more costly in forgone earnings.'},
{id:'P74-INC-BR-003',q:'A fee makes one more downtown trip costlier. How does marginal analysis describe the incentive?',options:['It raises the marginal cost of the next trip','It raises the total benefit of every past trip','It guarantees no one travels downtown','It removes the opportunity cost of alternatives'],answer:'It raises the marginal cost of the next trip',skill:'marginal_analysis_to_incentives',secondaryConceptIds:['marginal-analysis'],commonError:'Using totals instead of the changed payoff on the next action.',feedback:'The fee alters the next trip’s marginal cost, which can change the decision.'},
{id:'P74-INC-BR-004',q:'When a product’s price rises, buyers purchase less while sellers offer more. What common connection explains both responses?',options:['The price change creates different incentives for buyers and sellers','Buyers and sellers face identical benefits from the higher price','The higher price guarantees every buyer exits the market','Supply and demand responses require moral approval of the price'],answer:'The price change creates different incentives for buyers and sellers',skill:'incentives_to_supply_demand',secondaryConceptIds:['supply-and-demand'],commonError:'Assuming one price creates the same directional incentive on both sides.',feedback:'A higher price raises buyer cost while raising seller benefit.'},
{id:'P74-INC-BR-005',q:'A policy aims to reduce congestion but rewards agencies only for bus tickets sold. What lesson connects incentives to policy design?',options:['The rewarded measure may redirect behavior away from the stated policy objective','A stated goal automatically determines the behavioral margin','Ticket sales are identical to reduced congestion','An incentive exists only after congestion falls'],answer:'The rewarded measure may redirect behavior away from the stated policy objective',skill:'incentives_to_policy_design',secondaryConceptIds:['economist-policy-role'],commonError:'Confusing a stated purpose, measured target, and final outcome.',feedback:'Policy design must align the payoff with the behavior and outcome actually sought.'}
]};
const balanceOverrides={
'P74-INC-M-006':[1,'A larger statutory fine can never affect behavior when drivers know it exists'],'P74-INC-M-007':[1,'The bonus was not an incentive for either employee because their outcomes differed'],'P74-INC-M-008':[1,'The reward cannot be an incentive because cancellations rose after accepted jobs'],'P74-INC-H-005':[2,'It will ignore follow-up entirely because only direct procedure payments can ever affect hospital behavior'],'P74-INC-H-008':[1,'Raise the reward for submitting any low opening bid regardless of later change orders'],'P74-INC-H-009':[1,'Every patient reduces covered care by exactly the same percentage after the deductible change'],'P74-INC-H-010':[1,'Falling trust proves the citation reward cannot influence officer behavior or case priorities in any meaningful way'],'P74-INC-L-008':[1,'Weaker courses prove funding cannot influence completion decisions under any circumstances'],'P74-INC-L-010':[3,'Waiving a copay is not an incentive because patients receive no direct cash payment for attending preventive visits'],'P74-INC-L-011':[2,'The payment guarantees total food waste will decline throughout the entire city'],'P74-INC-L-012':[2,'The rule rewards every additional dollar of earnings with an equal dollar of net income'],'P74-INC-L-014':[1,'No incentive exists because public rankings do not directly change any worker’s cash wages'],'P74-INC-L-015':[2,'The donor did not face an incentive because the entire planned gift amount was chosen before the match'],'P74-INC-L-016':[3,'The rule is not an incentive until a seller is actually suspended after a reviewed complaint'],'P74-INC-L-017':[3,'Hidden durability cannot respond to incentives because inspectors cannot observe it during the initial contract review'],'P74-INC-FB-002':[3,'The policy has no incentive effect until every driver is caught and required to pay the posted fine'],'P74-INC-LB-004':[3,'A payment cannot affect headline choices unless it also changes the required length of every article'],'P74-INC-LB-005':[1,'The second household proves the surcharge is not an incentive because its electricity use cannot change'],'P74-INC-LB-009':[1,'Recorded doses are the incentive and the grant payment is merely the final health outcome'],'P74-INC-R-003':[1,'No; an incentive exists only when it changes the observed behavior in every single case'],'P74-INC-R-004':[1,'Yes; economic analysis always endorses any incentive whose likely response it successfully predicts'],'P74-INC-R-007':[2,'The fine guarantees compliance even when detection and enforcement are extremely unlikely']};
